def illustrated_is_prime(num):
    if num == 0 or num == 1:
        return False
    for i in range(2, num):
        if num % i == 0:
            return False
    return True

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, num):
        if num % i == 0:
            return False
    return True

# Regression test for the corrected integer-input function:
def test_negative_integer_is_not_prime():
    assert is_prime(-5) is False

class Inventory:
    def __init__(self, initial=None):
        self.stock = dict(initial or {})

    def get_stock(self, product):
        return self.stock.get(product, 0)

    def add_stock(self, product, quantity):
        if quantity < 0:
            raise ValueError("Quantity cannot be negative")
        self.stock[product] = self.get_stock(product) + quantity

    def remove_stock(self, product, quantity):
        if quantity < 0:
            raise ValueError("Quantity cannot be negative")
        if quantity > self.get_stock(product):
            raise ValueError("Insufficient stock")
        self.stock[product] = self.get_stock(product) - quantity

import pytest
from inventory import Inventory

@pytest.fixture
def inventory():
    return Inventory({"Notebook": 10})

def test_add_accumulates(inventory):
    inventory.add_stock("Notebook", 10)
    assert inventory.get_stock("Notebook") == 20

def test_remove_subtracts(inventory):
    inventory.remove_stock("Notebook", 3)
    assert inventory.get_stock("Notebook") == 7

def test_remove_too_many_raises(inventory):
    with pytest.raises(ValueError):
        inventory.remove_stock("Notebook", 20)
    assert inventory.get_stock("Notebook") == 10

def buggy_min(x, y):
    if x < y:
        return x
    else:
        return x  # BUG: should return y

def test_min_first_smaller():
    assert buggy_min(3, 8) == 3

def test_min_second_smaller():
    assert buggy_min(9, 4) == 4  # FAILS: actual is 9

def correct_min(x, y):
